<?php
require_once __DIR__.'/../includes/bootstrap.php';require_admin();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);try{
 if($action==='save'){$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');if($name==='')throw new RuntimeException('Category name is required.');$img=upload_image('image','categories');if($id){if($img){$st=$pdo->prepare("UPDATE categories SET name=?,description=?,image_path=? WHERE id=?");$st->execute([$name,$desc?:null,$img,$id]);}else{$st=$pdo->prepare("UPDATE categories SET name=?,description=? WHERE id=?");$st->execute([$name,$desc?:null,$id]);}}else{$st=$pdo->prepare("INSERT INTO categories(name,description,image_path) VALUES(?,?,?)");$st->execute([$name,$desc?:null,$img]);}flash('Category saved.');redirect('/lakshmi-electricals/admin/categories.php');}
 if($action==='delete'){$st=$pdo->prepare("SELECT COUNT(*) FROM products WHERE category_id=?");$st->execute([$id]);if((int)$st->fetchColumn()>0)throw new RuntimeException('This category has products. Reassign or remove those products first.');$st=$pdo->prepare("DELETE FROM categories WHERE id=?");$st->execute([$id]);flash('Category deleted.');redirect('/lakshmi-electricals/admin/categories.php');}
 }catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Could not save category. Check that the name is unique.';}}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare("SELECT * FROM categories WHERE id=?");$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}
$cats=$pdo->query("SELECT c.*,(SELECT COUNT(*) FROM products p WHERE p.category_id=c.id) product_count FROM categories c ORDER BY c.name")->fetchAll();
$pageTitle='Manage categories';require __DIR__.'/../includes/header.php';?>
<div class="admin-layout"><aside class="admin-sidebar"><span class="eyebrow">MANAGEMENT</span><h2>Admin panel</h2><a href="/lakshmi-electricals/admin/dashboard.php">Dashboard</a><a class="active" href="/lakshmi-electricals/admin/categories.php">Categories</a><a href="/lakshmi-electricals/admin/products.php">Products</a><a href="/lakshmi-electricals/admin/orders.php">Order requests</a><a href="/lakshmi-electricals/admin/users.php">Customers</a></aside><section class="admin-content"><div class="section-heading"><div><span class="eyebrow">CATALOGUE STRUCTURE</span><h1>Categories</h1></div></div><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><form class="form-card compact-form" method="post" enctype="multipart/form-data"><h2><?= $edit?'Edit category':'Add category' ?></h2><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>Category name<input name="name" maxlength="100" required value="<?= e($edit['name']??'') ?>"></label><label>Description<textarea name="description" rows="2"><?= e($edit['description']??'') ?></textarea></label><label>Category image (JPG, PNG, WEBP; max 3 MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><div class="form-actions"><button class="btn btn-gold">Save category</button><?php if($edit): ?><a class="btn btn-outline" href="/lakshmi-electricals/admin/categories.php">Cancel</a><?php endif; ?></div></form><div class="panel"><div class="table-scroll"><table><thead><tr><th>Category</th><th>Products</th><th>Actions</th></tr></thead><tbody><?php foreach($cats as $c): ?><tr><td><strong><?= e($c['name']) ?></strong><br><small><?= e($c['description']) ?></small></td><td><?= (int)$c['product_count'] ?></td><td><a class="text-link" href="?edit=<?= (int)$c['id'] ?>">Edit</a> <?php if(!(int)$c['product_count']): ?><form class="inline-delete" method="post" onsubmit="return confirm('Delete this category?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><button class="link-button danger">Delete</button></form><?php else: ?><small class="muted">Reassign products first</small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></section></div>
